']) ?></small><?php endif; ?></div><div class="field"><label for="capacity">Aircraft capacity</label><input id="capacity" name="capacity" type="number" min="1" max="999" inputmode="numeric" placeholder="14" required value="<?= $escape($values['capacity'] ?? '') ?>"><?php if (isset($errors['capacity'])): ?><small class="field-error"><?= $escape($errors['capacity']) ?></small><?php endif; ?></div><div class="field field--full"><label for="additional_request">Additional request <span class="optional">Optional</span></label><textarea id="additional_request" name="additional_request" maxlength="1500" placeholder="Catering, ground transport, preferred FBO or other requirements."><?= $escape($values['additional_request'] ?? '') ?></textarea><?php if (isset($errors['additional_request'])): ?><small class="field-error"><?= $escape($errors['additional_request']) ?></small><?php endif; ?></div><div class="field"><label for="total_amount">Total amount (USD)</label><input id="total_amount" name="total_amount" data-currency-input inputmode="decimal" autocomplete="off" placeholder="100,000.00" required value="<?= $escape($values['total_amount'] ?? '') ?>"><?php if (isset($errors['total_amount'])): ?><small class="field-error"><?= $escape($errors['total_amount']) ?></small><?php endif; ?></div><div class="field amount-words"><label>Amount in words</label><output data-amount-words><?= isset($values['total_cents']) ? $escape(\App\Invoice\InvoiceData::words((int) $values['total_cents'])) : 'Enter a total amount to preview the wording.' ?></output></div></div><div class="form-submit"><button class="button" type="submit">Generate PDF invoice</button><p>The invoice number is generated uniquely and the record is saved before the PDF is downloaded.</p></div>
